exercise.solution:
function loadConfig(env: Record<string, string | undefined>) {
  const problems: string[] = [];

  let port = 8080;
  if (env.PORT !== undefined) {
    const parsed = Number(env.PORT);
    if (!Number.isInteger(parsed) || parsed < 1 || parsed > 65535) {
      problems.push("PORT must be an integer between 1 and 65535");
    } else {
      port = parsed;
    }
  }

  const databaseUrl = env.DATABASE_URL;
  if (!databaseUrl) {
    problems.push("DATABASE_URL is required");
  } else if (!databaseUrl.startsWith("jdbc:postgresql://")) {
    problems.push("DATABASE_URL must start with jdbc:postgresql://");
  }

  const corsOrigins = env.CORS_ORIGINS === undefined
    ? []
    : env.CORS_ORIGINS
        .split(",")
        .map((origin) => origin.trim())
        .filter((origin) => origin.length > 0);

  const profile = env.APP_PROFILE === undefined ? "dev" : env.APP_PROFILE;
  if (profile !== "dev" && profile !== "prod") {
    problems.push("APP_PROFILE must be dev or prod");
  }

  const jwtSecret = env.JWT_SECRET;
  if (!jwtSecret) {
    problems.push("JWT_SECRET is required");
  } else if (profile === "prod" && jwtSecret.length < 32) {
    problems.push("JWT_SECRET must be at least 32 characters in prod");
  }

  if (profile === "prod" && corsOrigins.includes("*")) {
    problems.push("CORS_ORIGINS must not contain * in prod");
  }

  if (problems.length > 0) {
    throw new Error(`Invalid config: ${problems.join("; ")}`);
  }

  return {
    port,
    databaseUrl,
    corsOrigins,
    profile,
    jwtSecret
  };
}

function redact(config: {
  port: number;
  databaseUrl: string;
  corsOrigins: string[];
  profile: "dev" | "prod";
  jwtSecret: string;
}) {
  const databaseUrl = config.databaseUrl.replace(/(password=)[^&]*/i, "$1***");

  return {
    ...config,
    databaseUrl,
    corsOrigins: [...config.corsOrigins],
    jwtSecret: "***"
  };
}

