const config = loadConfig({
  DATABASE_URL: "jdbc:postgresql://localhost:5432/shop",
  JWT_SECRET: "dev-secret"
});
return config.port === 8080 &&
  config.databaseUrl === "jdbc:postgresql://localhost:5432/shop" &&
  JSON.stringify(config.corsOrigins) === "[]" &&
  config.profile === "dev" &&
  config.jwtSecret === "dev-secret";

const secret = "12345678901234567890123456789012";
const config = loadConfig({
  PORT: "8443",
  DATABASE_URL: "jdbc:postgresql://db.example.com:5432/shop",
  CORS_ORIGINS: "https://shop.example.com, https://admin.example.com",
  APP_PROFILE: "prod",
  JWT_SECRET: secret
});
return config.port === 8443 &&
  JSON.stringify(config.corsOrigins) === JSON.stringify(["https://shop.example.com", "https://admin.example.com"]) &&
  config.profile === "prod" &&
  config.jwtSecret === secret;

const cases = ["0", "65536", "1.5", "abc"];
for (const PORT of cases) {
  try {
    loadConfig({ PORT, DATABASE_URL: "jdbc:postgresql://db/shop", JWT_SECRET: "secret" });
    return false;
  } catch (error) {
    if (!String(error?.message).startsWith("Invalid config:") || !String(error?.message).includes("PORT")) return false;
  }
}
return true;

