const config = {
  port: 8080,
  databaseUrl: "jdbc:postgresql://shop:secret@db:5432/shop?sslmode=require&password=my-password&connectTimeout=5",
  corsOrigins: ["https://shop.example.com"],
  profile: "prod",
  jwtSecret: "very-secret-value"
};
const original = JSON.stringify(config);
const redacted = redact(config);
return redacted !== config &&
  redacted.jwtSecret === "***" &&
  redacted.databaseUrl.includes("password=***") &&
  !redacted.databaseUrl.includes("password=my-password") &&
  redacted.port === 8080 &&
  JSON.stringify(redacted.corsOrigins) === JSON.stringify(config.corsOrigins) &&
  redacted.corsOrigins !== config.corsOrigins &&
  JSON.stringify(config) === original;
